            if len(lists[i]) != len(lists[j]):
                return False
    return True


def add_lists(lists: List[List[int]]) -> List[int]:
    """ Adds each element in a list with the corresponding element in another list.
    >>> add_lists([[1, 2], [10, 20]])
    [11, 22]
    """
    result = []
    for i in range(len(lists[0])):
        sum = 0
        for j in range(len(lists)):
            sum += lists[j][i]
        result.append(sum)
    return result


def matrix_sum(matrix: List[List[int]]) -> int:
    """ Returns a sum of sums of rows of the matrix.
    >>> matrix_sum([[1, -2], [-3, 4]])
    0
    >>> matrix_sum([[2, 4, 6], [-8], [3, 6.5]])
    10.5
    """
    return sum(sum(row) for row in matrix)


