def roman_to_int(s: str) -> int:
    """ Given a Roman numeral, convert it to an integer.
    >>> roman_to_int('III')
    3
    """
    roman_values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = 0
    for i in range(len(s)):
        if i > 0 and roman_values[s[i]] > roman_values[s[i - 1]]:
            result += roman_values[s[i]] - 2 * roman_values[s[i - 1]]
        else:
            result += roman_values[s[i]]
    return result


def longest_palindromic_substring(s: str) -> str:
    """ Given a string, find the longest palindromic substring.
    >>> longest_palindromic_substring('babad')
    'bab'
    """
    result = ''
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            if s[i:j] == s[i:j][::-1]:
                result = max(result, s[i:j], key=len)
    return result


def valid_parentheses(s: str) -> bool:
    """ Given a string containing just the characters '(', ')', '{', '}', '[' and ']',
    determine if the input string is valid.
    >>> valid_parentheses('()[]{}')
    True
    """
    stack = []
    for char in s:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack:
                return False
            if char == ')' and stack[-1] != '(':
                return False
            if char == ']' and stack[-1] != '[':
                return False
            if char == '}' and stack[-1] != '{':
                return False
            stack.pop()
    return not stack


def reverse_integer(x: int) -> int:
    """ Given a 32-bit signed integer, reverse digits of an integer.
    >>> reverse_integer(123)
    321
    """
    result = 0
    sign = -1 if x < 0 else 1
    x = abs(x)
    while x:
        result = result * 10 + x % 10
        x //= 10
    return 0 if result > pow(2, 31) else result * sign


def reverse_words(s: str) -> str:
    """ Given a string, you need to reverse the order of characters in each word within a sentence
    while still preserving whitespace and initial word order.
    >>> reverse_words('Let's take LeetCode contest')
    "s'teL ekat edoCteeL tsetnoc"
    """
    return ' '.join([word[::-1] for word in s.split()])


def find_all_anagrams(s: str, p: str) -> List[int]:
    """ Given a string s and a non-empty string p, find all the start indices of p's anagrams in s.
    >>> find_all_anagrams('abab', 'ab')
    [0, 1, 2]
    """
    result = []
    p_len = len(p)
    for i in range(len(s) - p_len + 1):
        if sorted(s[i:i + p_len]) == sorted(p):
            result.append(i)
    return result


def zigzag_conversion(s: str, numRows: int) -> str:
    """ The string "PAYPALISHIRING" is written in a zigzag pattern on a given number of rows
    like this: (you may want to display this pattern in a fixed font for better legibility)
    >>> zigzag_conversion('PAYPALISHIRING', 3)
    'PAHNAPLSIIGYIR'
    """
    if numRows == 1:
        return s
    result = [''] * numRows
    row = 0
    direction = -1
    for char in s:
        result[row] += char
        if row == 0 or row == numRows - 1:
            direction = -direction
        row += direction
    return ''.join(result)


