def increment_nested_parens(paren_string: str) -> str:
    """ Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, increase the nesting level of the parentheses by one and return the combined result.

    >>> increment_nested_parens('(()()) ((())) ()')
    '(((()))) (((()))) ()'
    """
    output = []
    for group in paren_string.split(' '):
        if not group:
            output.append(group)
        else:
            output.append('(' + group + ')')
    return ' '.join(output)


