        return bisection(x_start, x_mid)

    return bisection(x_start, x_end)


def coeff(zeros: list):
    """Returns coefficients of a polynomial with roots zeros"""
    product = [1]  # product is polynomial as a list of its coefficients
    for zero in zeros:
        # (x - zero) = 1 * x^1 - 1 * x^0
        p = [1, -zero]
        acc = [0] * (len(product) + len(p))  # acc is accumulator
        for i, coeff_p in enumerate(p):
            for j, coeff_prod in enumerate(product):
                acc[i + j] += coeff_p * coeff_prod
        product = acc
    return product


def roots(xs: list):
    """ xs are coefficients of a polynomial.
    roots returns all roots of poly(xs, x) = 0
    >>> roots([1, 2]) # 1 + 2x = 0, x = -1 / 2
    [-0.5]
    >>> roots([-6, 11, -6, 1]) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    [1.0, 2.0, 3.0]
    """
    zeros = []
    n = len(xs)
    if n == 2:
        return [-xs[1] / xs[0]]
    zeros = [find_zero(xs)]
    xs_reduced = coeff(zeros)  # Reduced polynomial with same roots as xs
    # but the one we already know
    # xs_reduced has coefficients xs[:n-1]
    # xs_reduced = xs / (x - zero)
    return zeros + roots(xs_reduced[:n - 1])


