    """ This function takes an image and returns a new image where the red, green, and blue values of each pixel are set to the average of the original values."""
    width, height = image.width(), image.height()
    new_image = Image(width, height)
    for x in range(width):
        for y in range(height):
            pixel = image.get_pixel(x, y)
