    """ This function takes an image and returns a new image where the image is flipped horizontally."""
    width, height = image.width(), image.height()
    new_image = Image(width, height)
    for x in range(width):
        for y in range(height):
            pixel = image.get_pixel(x, y)
            new_image.set_pixel(width - x - 1, y, pixel)
    return new_image

def scale(image: Image, factor: float) -> Image:
    """ This function takes an image and a scaling factor and returns a new image where the image is scaled by the scaling factor."""
    width, height = image.width(), image.height()
    new_image = Image(int(width * factor), int(height * factor))
    for x in range(new_image.width()):
        for y in range(new_image.height()):
            new_image.set_pixel(x, y, image.get_pixel(int(x / factor), int(y / factor)))
    return new_image

