def find_dirs(root_dir, suffix=".bin", append_dir=False):
    """
    Find all directories under root_dir that contain files with the given suffix

    Args:
        root_dir (str): root directory
        suffix (str): file suffix, will search for files with this suffix
        append_dir (bool): if True, append the root_dir to the returned path

    Returns:
        dirs (list): list of directories containing files with the given suffix
    """
    dirs = []
    for dirpath, dirnames, filenames in os.walk(root_dir):
        if len(filenames) > 0:
            if suffix in filenames[0]:
                if append_dir:
                    dirs.append(os.path.join(root_dir, dirpath))
                else:
                    dirs.append(dirpath)
    return dirs

