        append_dir (bool): if True, append the root_dir to the returned path
        sort (bool): if True, sort the files

    Returns:
        files (list): list of files with the given suffix
    """
    files = []
    for dirpath, dirnames, filenames in os.walk(root_dir):
        for f in filenames:
