def extended_euclid(first_digit: int, second_digit: int) -> (int, int, int):
    """Extended Euclid algorithm"""
    a0 = 0
    b0 = 1
    a1 = 1
    b1 = 0
    while second_digit != 0:
        temp = division(first_digit, second_digit)
        a0, a1 = a1, a0 - temp[0] * a1
        b0, b1 = b1, b0 - temp[0] * b1
        first_digit, second_digit = second_digit, temp[1]
    return first_digit, a0, b0


