def circular_index(input_sequence: List[int], target_sum: int) -> int:
    """
    Given a circular sequence (i.e. the sequence starts with the last element and ends with
    the first element), find the smallest index such that the sum of all the elements from
    that index to the end of the sequence is at least target_sum.
    """
    for i in range(len(input_sequence)):
        if sum(input_sequence[i:] + input_sequence[:i]) >= target_sum:
            return i
    return -1

