def eval_tree(tree):
    """Return the result of evaluating the tree.
    A leaf is a tuple (leaf, value).
    An internal node is a tuple (internal, left, right).
    The evaluation of a leaf is its value.
    The evaluation of an internal node is the evaluation of its left child plus the evaluation of its right child.
    >>> eval_tree((1, 2))
    3
    """
    if isinstance(tree, tuple):
        if tree[0] == "leaf":
            return tree[1]
        else:
            return eval_tree(tree[1]) + eval_tree(tree[2])
    else:
        return tree


